import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/outlierr/2021_energy.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

# Load data
energy_df = pd.read_csv(DATASET_PATH)
adjacency_df = pd.read_csv(ADJACENCY_PATH)

# Create energy dictionary
energy_dict = dict(zip(energy_df['borough'], energy_df['Energy_value']))

# Build neighbors dictionary
neighbors_dict = {}
for _, row in adjacency_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighbors_dict:
        neighbors_dict[borough] = []
    neighbors_dict[borough].append(neighbor)

# Prepare regression data (excluding City of London)
regression_data = []
for index, row in energy_df.iterrows():
    borough_name = row['borough']
    if borough_name == 'City of London':
        continue
    if borough_name not in neighbors_dict:
        continue  # No neighbors
    neighbors = neighbors_dict[borough_name]
    neighbor_energies = []
    for neighbor in neighbors:
        if neighbor in energy_dict:
            neighbor_energies.append(energy_dict[neighbor])
    if len(neighbor_energies) == 0:
        continue
    avg_neighbor_energy = np.mean(neighbor_energies)
    regression_data.append({
        'neighbor_avg': avg_neighbor_energy,
        'energy': row['Energy_value']
    })

regression_df = pd.DataFrame(regression_data)

# Perform linear regression
if not regression_df.empty:
    X = regression_df['neighbor_avg'].values
    y = regression_df['energy'].values
    X_with_intercept = np.column_stack((np.ones_like(X), X))
    coefficients, _, _, _ = np.linalg.lstsq(X_with_intercept, y, rcond=None)
    a, b = coefficients
else:
    a, b = 0, 0  # Fallback if no data

# Compute for City of London
city_borough = 'City of London'
if city_borough in energy_dict:
    city_energy = energy_dict[city_borough]
    if city_borough in neighbors_dict:
        city_neighbors = neighbors_dict[city_borough]
        neighbor_energies = []
        for neighbor in city_neighbors:
            if neighbor in energy_dict:
                neighbor_energies.append(energy_dict[neighbor])
        if len(neighbor_energies) > 0:
            city_neighbor_avg = np.mean(neighbor_energies)
            predicted_energy = a + b * city_neighbor_avg
            residual = city_energy - predicted_energy
            # Compute residuals for all other boroughs
            residuals = y - (a + b * X)
            residual_std = np.std(residuals, ddof=1)
            if residual_std != 0:
                z_score = residual / residual_std
                if abs(z_score) > 2:
                    if residual > 0:
                        print(f"FINAL ANSWER: OUTLIER - HIGH (z = {z_score:.4f})")
                    else:
                        print(f"FINAL ANSWER: OUTLIER - LOW (z = {z_score:.4f})")
                else:
                    print(f"FINAL ANSWER: NOT AN OUTLIER (z = {z_score:.4f})")
            else:
                print("FINAL ANSWER: NOT AN OUTLIER (z = 0.0)")
        else:
            print("City of London has no valid neighbors in energy data.")
    else:
        print("City of London has no neighbors.")
else:
    print("City of London not found in energy data.")
